contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public function with all test logic.
    // Inputs: a guess hash and an amount to forward to lockInGuess.
    function run(bytes32 guessHash, uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // only constrain the parameters (have enough balance to forward)
        require(address(this).balance >= sendAmount);

        // record balances before any interaction
        uint256 beforeTester = address(this).balance;
        uint256 beforeC = address(c).balance;

        // Attempt lockInGuess; it may revert. Must be a top-level statement.
        bool lockReverted;
        c.lockInGuess{value: sendAmount}(guessHash); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            lockReverted = true;
        } else {
            lockReverted = false;
        }

        // balances immediately after lock attempt
        uint256 afterLockTester = address(this).balance;
        uint256 afterLockC = address(c).balance;

        // Now attempt settle; it may revert. Must be top-level statement.
        bool settleReverted;
        c.settle(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            settleReverted = true;
        } else {
            settleReverted = false;
        }

        // final balances
        uint256 finalTester = address(this).balance;
        uint256 finalC = address(c).balance;

        // Assert the general rule as one formula:
        // Either lockInGuess reverted and nothing observable changed at the moment of the call,
        // and settle could not have increased the tester's balance above beforeTester (no free money),
        // OR lockInGuess succeeded, in which case it must have transferred exactly 1 ether into c
        // (so tester lost 1 ether and c gained 1 ether immediately), and overall Ether is conserved
        // between tester and c across the whole sequence, and if settle succeeded then tester's net
        // gain relative to beforeTester is at most 2 ether (contract pays at most 2 ether on win).
        assert(
            (
                // Case A: lockInGuess reverted -> no change from before to afterLock
                lockReverted
                && afterLockTester == beforeTester
                && afterLockC == beforeC
                // settle cannot have created ether for the tester beyond before (no free creation)
                && finalTester <= beforeTester
                && finalC >= beforeC
            )
            ||
            (
                // Case B: lockInGuess succeeded
                !lockReverted
                // lockInGuess requires exactly 1 ether to succeed, so balances must reflect that
                && afterLockTester + 1 ether == beforeTester
                && afterLockC == beforeC + 1 ether
                // Conservation of Ether across the whole interaction between tester and c
                && (finalC - beforeC) == (beforeTester - finalTester)
                // If settle succeeded, the tester's net gain cannot exceed 2 ether
                && (settleReverted || finalTester <= beforeTester + 2 ether)
            )
        );
    }

    // accept Ether so this contract can fund lockInGuess
    receive() external payable {}
}

