// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(bytes32 guessHash, uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        uint256 beforeTester = address(this).balance;
        uint256 beforeC = address(c).balance;
        bool lockReverted;
        try c.lockInGuess{value: sendAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }
        uint256 afterLockTester = address(this).balance;
        uint256 afterLockC = address(c).balance;
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint256 finalTester = address(this).balance;
        uint256 finalC = address(c).balance;
        assertTrue((
                // Case A: lockInGuess reverted -> no change from before to afterLock
                lockReverted
                && afterLockTester == beforeTester
                && afterLockC == beforeC
                // settle cannot have created ether for the tester beyond before (no free creation)
                && finalTester <= beforeTester
                && finalC >= beforeC
            )
            ||
            (
                // Case B: lockInGuess succeeded
                !lockReverted
                // lockInGuess requires exactly 1 ether to succeed, so balances must reflect that
                && afterLockTester + 1 ether == beforeTester
                && afterLockC == beforeC + 1 ether
                // Conservation of Ether across the whole interaction between tester and c
                && (finalC - beforeC) == (beforeTester - finalTester)
                // If settle succeeded, the tester's net gain cannot exceed 2 ether
                && (settleReverted || finalTester <= beforeTester + 2 ether)
            ));
    }

    function testFuzz_run(bytes32 guessHash, uint256 sendAmount) public {
        _run(guessHash, sendAmount);
    }

    receive() external payable {}
}
